local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function base64decode(data)
    data = data:gsub("[^" .. alphabet .. "=]", "")
    local out, pos = {}, 1
    local function val(c) return alphabet:find(c, 1, true) - 1 end
    while pos <= #data do
        local a,b,c,d = data:sub(pos,pos),data:sub(pos+1,pos+1),data:sub(pos+2,pos+2),data:sub(pos+3,pos+3)
        if a == "" then break end
        local av,bv = val(a), b ~= "" and val(b) or 0
        local cv = c ~= "" and c ~= "=" and val(c) or 0
        local dv = d ~= "" and d ~= "=" and val(d) or 0
        out[#out+1] = string.char(av*4+math.floor(bv/16))
        if c ~= "" and c ~= "=" then out[#out+1] = string.char((bv%16)*16+math.floor(cv/4)) end
        if d ~= "" and d ~= "=" then out[#out+1] = string.char((cv%4)*64+dv) end
        pos = pos + 4
    end
    return table.concat(out)
end

-- Compact LZ4 block decoder.
local function lz4decode(data)
    local chunks, chars = {}, {}
    local ring = {}
    local ringPos = 0
    local charCount = 0
    local function emit(b)
        ringPos = ringPos + 1
        ring[(ringPos - 1) % 65536] = b
        charCount = charCount + 1
        chars[#chars + 1] = string.char(b)
        if #chars >= 4096 then
            chunks[#chunks + 1] = table.concat(chars)
            chars = {}
        end
    end
    local function emitRange(data, i, len)
        for j = i, i + len - 1 do emit(data:byte(j)) end
        return i + len
    end
    local i, n = 1, #data
    while i <= n do
        local token = data:byte(i); i = i + 1
        local litLen = math.floor(token / 16)
        if litLen == 15 then
            repeat
                local x = data:byte(i); i = i + 1
                litLen = litLen + x
            until x ~= 255
        end
        if litLen > 0 then i = emitRange(data, i, litLen) end
        if i > n then break end
        local lo, hi = data:byte(i), data:byte(i + 1); i = i + 2
        local offset = lo + hi * 256
        local matchLen = token % 16
        if matchLen == 15 then
            repeat
                local x = data:byte(i); i = i + 1
                matchLen = matchLen + x
            until x ~= 255
        end
        matchLen = matchLen + 4
        for _ = 1, matchLen do
            local b = ring[(ringPos - offset) % 65536]
            emit(b)
        end
    end
    if #chars > 0 then chunks[#chunks + 1] = table.concat(chars) end
    return table.concat(chunks)
end

